bool Volume::stat(const char*p,uint64_t*n,bool*d){if(n)*n=0;if(d)*d=false;if(!owner()||!ready_||!n||!d||!valid(p))return false;if(!strcmp(p,"/")){*d=true;return true;}int i=find(image_,p);if(i<0)return false;const auto*r=row(image_,unsigned(i));*d=word(r+Path)==1;*n=word(r+Path+4);return true;}
uint32_t Volume::openRead(const char*p,uint64_t*n){uint64_t size=0;bool dir=false;if(reader_||!stat(p,&size,&dir)||dir||handles_==UINT32_MAX)return 0;readIndex_=unsigned(find(image_,p));reader_=++handles_;position_=0;handleError_=0;if(n)*n=size;return reader_;}
