uint32_t Volume::dirOpen(const char*p){uint64_t n;bool d;if(directory_||!stat(p,&n,&d)||!d||handles_==UINT32_MAX)return 0;strcpy(directoryPath_,p);dirPosition_=0;directory_=++handles_;handleError_=0;return directory_;}
bool Volume::dirNext(uint32_t h,risc_storage_dirent_v1*out){if(!owner()||!ready_||!h||h!=directory_||!out)return false;size_t prefix=strlen(directoryPath_);while(dirPosition_<word(image_+8)){const auto*r=row(image_,dirPosition_++);const char*p=reinterpret_cast<const char*>(r);if(strncmp(p,directoryPath_,prefix))continue;const char*name=p+prefix;if(prefix>1){if(*name++!='/')continue;}if(!*name||strchr(name,'/'))continue;memset(out,0,sizeof(*out));strcpy(out->name,name);out->size=word(r+Path+4);out->is_directory=uint8_t(word(r+Path));return true;}return false;}
bool Volume::dirClose(uint32_t h){if(!owner()||!h||h!=directory_)return false;directory_=0;return true;}
bool Volume::mkdir(const char*p){if(!owner()||!ready_||!idle()||!valid(p)||!strcmp(p,"/")||find(image_,p)>=0||!parent(image_,p)||word(image_+8)>=Entries)return false;memcpy(stage_,image_,bytes_);unsigned i=word(stage_+8);auto*r=row(stage_,i);memset(r,0,Record);strcpy(reinterpret_cast<char*>(r),p);word(r+Path,1);word(r+Path+8,bytes_);word(stage_+8,i+1);return save(stage_,bytes_);}
